      ring: '#ffb347',
    },
  },
  {
    name: 'pastel',
    label: 'Pastel',
    colors: {
      bg: '#1e1e2e',
      fg: '#cdd6f4',
      dim: '#7f849c',
      conversation: '#cba6f7',
      roleplay: '#fab387',
